// Package vectors loads the golden vectors in testdata/vectors for the
// signer's tests. The vectors are CC0 data generated by tools/vectorgen with
// qrysm as the oracle (testdata/vectors/README.md); this package only reads
// them, so it shares no code with qrysm. Only _test files import it.
package vectors

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// Presets are the fixture presets: minimal is the end-to-end network,
// mainnet the end-to-end-mainnet network.
var Presets = []string{"minimal", "mainnet"}

// Dir returns the absolute path of testdata/vectors.
func Dir() string {
	_, file, _, _ := runtime.Caller(0)
	return filepath.Join(filepath.Dir(file), "..", "..", "testdata", "vectors")
}

// Network is the per-record network of a fixture.
type Network struct {
	ConfigName         string `json:"config_name"`
	GenesisForkVersion string `json:"genesis_fork_version"`
	GVR                string `json:"gvr"`
	SlotsPerEpoch      string `json:"slots_per_epoch"`
}

// Expect is a fixture's expected response.
type Expect struct {
	Status int    `json:"status"`
	Reason string `json:"reason"`
}

// Block is the full and blinded block behind a BLOCK_V2 header.
type Block struct {
	FullSSZHex    string `json:"full_ssz_hex"`
	FullRoot      string `json:"full_root"`
	BlindedSSZHex string `json:"blinded_ssz_hex"`
	BlindedRoot   string `json:"blinded_root"`
}

// SignCase is a golden sign request (signing/<preset>/<type>.json).
type SignCase struct {
	Name                   string          `json:"name"`
	Type                   string          `json:"type"`
	Preset                 string          `json:"preset"`
	Network                Network         `json:"network"`
	KeyIndex               int             `json:"key_index"`
	Pubkey                 string          `json:"pubkey"`
	ObjectSSZHex           string          `json:"object_ssz_hex"`
	ObjectRoot             string          `json:"object_root"`
	Domain                 string          `json:"domain"`
	SigningRoot            string          `json:"signing_root"`
	RequestJSON            json.RawMessage `json:"request_json"`
	DeterministicSignature string          `json:"deterministic_signature"`
	Block                  *Block          `json:"block"`
	Authoritative          *bool           `json:"authoritative"`
	Notes                  string          `json:"notes"`
	Expect                 Expect          `json:"expect"`
}

// ID names the case in test output.
func (c *SignCase) ID() string { return c.Preset + "/" + c.Type + "/" + c.Name }

// RootCase is a seed-expanded random object's roots.
type RootCase struct {
	Seed        uint64 `json:"seed"`
	ObjectRoot  string `json:"object_root"`
	Domain      string `json:"domain"`
	SigningRoot string `json:"signing_root"`
}

// RootFile is roots/<preset>/<type>.json.
type RootFile struct {
	Type                 string     `json:"type"`
	Preset               string     `json:"preset"`
	Network              Network    `json:"network"`
	SyncSubcommitteeBits uint64     `json:"sync_subcommittee_bits"`
	Cases                []RootCase `json:"cases"`
}

// NegativeCase is a request the signer refuses.
type NegativeCase struct {
	Name       string `json:"name"`
	Type       string `json:"type"`
	KeyIndex   int    `json:"key_index"`
	Identifier string `json:"identifier"`
	Signer     *struct {
		VoluntaryExitsEnabled *bool `json:"voluntary_exits_enabled"`
	} `json:"signer"`
	RequestBody string `json:"request_body"`
	Expect      Expect `json:"expect"`
}

// NegativeFile is negative/<preset>.json.
type NegativeFile struct {
	Preset  string         `json:"preset"`
	Network Network        `json:"network"`
	Cases   []NegativeCase `json:"cases"`
}

// Key is an interop key of keys/interop.json.
type Key struct {
	Index             int    `json:"index"`
	Seed              string `json:"seed"`
	Pubkey            string `json:"pubkey"`
	RandaoCommitment  string `json:"randao_commitment"`
	RandaoFirstReveal string `json:"randao_first_reveal"`
}

// KeystoreCase is an entry of keystores/index.json: a keystore file and
// the password, seed and public key it holds.
type KeystoreCase struct {
	File     string `json:"file"`
	Flavour  string `json:"flavour"` // qrl-v1 or deposit-cli
	KDF      KDF    `json:"kdf"`
	Password string `json:"password"`
	KeyIndex int    `json:"key_index"`
	Seed     string `json:"seed"`
	Pubkey   string `json:"pubkey"`
}

// KDF is a keystore's Argon2id parameters as index.json records them.
type KDF struct {
	Function string `json:"function"`
	T        int    `json:"t"`
	M        int    `json:"m"`
	P        int    `json:"p"`
}

// NetworkInfo is an entry of networks.json.
type NetworkInfo struct {
	Name                           string `json:"name"`
	ConfigName                     string `json:"config_name"`
	PresetBase                     string `json:"preset_base"`
	GenesisForkVersion             string `json:"genesis_fork_version"`
	SecondsPerSlot                 string `json:"seconds_per_slot"`
	SlotsPerEpoch                  string `json:"slots_per_epoch"`
	DepositChainID                 string `json:"deposit_chain_id"`
	DepositNetworkID               string `json:"deposit_network_id"`
	SyncCommitteeSize              string `json:"sync_committee_size"`
	SyncCommitteeSubnetCount       string `json:"sync_committee_subnet_count"`
	MinGenesisActiveValidatorCount string `json:"min_genesis_active_validator_count"`
	InteropGenesisValidatorsRoot   string `json:"interop_genesis_validators_root"`
}

// GenesisPrefix is networks/genesis-state-prefix.json.
type GenesisPrefix struct {
	Network               string `json:"network"`
	SSZPrefixHex          string `json:"ssz_prefix_hex"`
	GenesisTime           string `json:"genesis_time"`
	GenesisValidatorsRoot string `json:"genesis_validators_root"`
	Slot                  string `json:"slot"`
	Fork                  struct {
		PreviousVersion string `json:"previous_version"`
		CurrentVersion  string `json:"current_version"`
		Epoch           string `json:"epoch"`
	} `json:"fork"`
}

// Layer is an onion layer value.
type Layer struct {
	Index uint64 `json:"index"`
	Value string `json:"value"`
}

// OnionVector is one of V1-V3 (randao/onion.json).
type OnionVector struct {
	ID         string  `json:"id"`
	Seed       string  `json:"seed"`
	Layers     uint64  `json:"layers"`
	Values     []Layer `json:"values"`
	Commitment string  `json:"commitment"`
	Reveal     string  `json:"reveal"`
}

// InteropCommitments is V4 (randao/interop.json).
type InteropCommitments struct {
	Layers uint64 `json:"layers"`
	Keys   []struct {
		Index       int    `json:"index"`
		Seed        string `json:"seed"`
		Commitment  string `json:"commitment"`
		FirstReveal string `json:"first_reveal"`
	} `json:"keys"`
}

// RandaoRequest is a V5 request (randao/requests.json).
type RandaoRequest struct {
	Name             string          `json:"name"`
	Preset           string          `json:"preset"`
	KeyIndex         int             `json:"key_index"`
	SlotOffset       int64           `json:"slot_offset"`
	RandaoCommitment string          `json:"randao_commitment"`
	ForkInfo         json.RawMessage `json:"fork_info"`
	Expect           Expect          `json:"expect"`
}

// FrontierStep is a step of a V6 script.
type FrontierStep struct {
	NowSlot          string  `json:"now_slot"`
	Slot             string  `json:"slot"`
	CommitmentLayer  *uint64 `json:"commitment_layer"`
	RandaoCommitment string  `json:"randao_commitment"`
	Expect           struct {
		Status       int     `json:"status"`
		Reason       string  `json:"reason"`
		RevealLayer  *uint64 `json:"reveal_layer"`
		RandaoReveal string  `json:"randao_reveal"`
		Result       string  `json:"result"`
		State        *struct {
			M      uint64 `json:"m"`
			Reveal string `json:"reveal"`
			Last   string `json:"last"`
		} `json:"state"`
	} `json:"expect"`
}

// Frontier is V6 (randao/frontier.json).
type Frontier struct {
	Network  string  `json:"network"`
	KeyIndex int     `json:"key_index"`
	Layers   []Layer `json:"layers"`
	Scripts  []struct {
		Name     string `json:"name"`
		Scenario string `json:"scenario"`
		Signer   struct {
			RandaoMaxLayers                uint64 `json:"randao_max_layers"`
			RandaoReorgWindow              uint64 `json:"randao_reorg_window"`
			SigningClockSkewSlots          uint64 `json:"signing_clock_skew_slots"`
			RandaoNewLayerBurst            uint64 `json:"randao_new_layer_burst"`
			RandaoNewLayerRefillEpochs     uint64 `json:"randao_new_layer_refill_epochs"`
			RandaoFullScanMinIntervalSlots uint64 `json:"randao_full_scan_min_interval_slots"`
		} `json:"signer"`
		Steps []FrontierStep `json:"steps"`
	} `json:"scripts"`
}

var cache sync.Map // relative path -> []byte

// Load decodes the fixture file at rel (relative to Dir) into v. Files are
// read once per test binary.
func Load(t testing.TB, rel string, v any) {
	t.Helper()
	b, ok := cache.Load(rel)
	if !ok {
		data, err := os.ReadFile(filepath.Join(Dir(), filepath.FromSlash(rel)))
		if err != nil {
			t.Fatalf("golden vectors: %v (regenerate with make vectors)", err)
		}
		b, _ = cache.LoadOrStore(rel, data)
	}
	if err := json.Unmarshal(b.([]byte), v); err != nil {
		t.Fatalf("golden vectors: %s: %v", rel, err)
	}
}

// files returns the fixture files matching pattern (relative to Dir).
func files(t testing.TB, pattern string) []string {
	t.Helper()
	m, err := filepath.Glob(filepath.Join(Dir(), filepath.FromSlash(pattern)))
	if err != nil {
		t.Fatal(err)
	}
	if len(m) == 0 {
		t.Fatalf("golden vectors: nothing matches %s (regenerate with make vectors)", pattern)
	}
	out := make([]string, len(m))
	for i, p := range m {
		rel, err := filepath.Rel(Dir(), p)
		if err != nil {
			t.Fatal(err)
		}
		out[i] = filepath.ToSlash(rel)
	}
	return out
}

// Signing returns every golden sign request of both presets.
func Signing(t testing.TB) []SignCase {
	t.Helper()
	var out []SignCase
	for _, f := range files(t, "signing/*/*.json") {
		var sf struct {
			Cases []SignCase `json:"cases"`
		}
		Load(t, f, &sf)
		out = append(out, sf.Cases...)
	}
	return out
}

// Roots returns every random-root file of both presets.
func Roots(t testing.TB) []RootFile {
	t.Helper()
	var out []RootFile
	for _, f := range files(t, "roots/*/*.json") {
		var rf RootFile
		Load(t, f, &rf)
		out = append(out, rf)
	}
	return out
}

// Negative returns the negative fixtures of both presets.
func Negative(t testing.TB) []NegativeFile {
	t.Helper()
	out := make([]NegativeFile, 0, len(Presets))
	for _, p := range Presets {
		var nf NegativeFile
		Load(t, "negative/"+p+".json", &nf)
		out = append(out, nf)
	}
	return out
}

// Keys returns the interop keys of keys/interop.json.
func Keys(t testing.TB) []Key {
	t.Helper()
	var f struct {
		Keys []Key `json:"keys"`
	}
	Load(t, "keys/interop.json", &f)
	return f.Keys
}

// Keystores returns the entries of keystores/index.json.
func Keystores(t testing.TB) []KeystoreCase {
	t.Helper()
	var f struct {
		Keystores []KeystoreCase `json:"keystores"`
	}
	Load(t, "keystores/index.json", &f)
	return f.Keystores
}

// Raw returns the bytes of the fixture file at rel (relative to Dir).
func Raw(t testing.TB, rel string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(Dir(), filepath.FromSlash(rel)))
	if err != nil {
		t.Fatalf("golden vectors: %v (regenerate with make vectors)", err)
	}
	return data
}

// Networks returns networks.json.
func Networks(t testing.TB) []NetworkInfo {
	t.Helper()
	var f struct {
		Networks []NetworkInfo `json:"networks"`
	}
	Load(t, "networks.json", &f)
	return f.Networks
}

// NetworkByConfigName returns the networks.json entry named name.
func NetworkByConfigName(t testing.TB, name string) NetworkInfo {
	t.Helper()
	for _, n := range Networks(t) {
		if n.ConfigName == name {
			return n
		}
	}
	t.Fatalf("golden vectors: no network %q", name)
	return NetworkInfo{}
}

// Hex decodes a 0x-prefixed hex string or fails the test.
func Hex(t testing.TB, s string) []byte {
	t.Helper()
	h, ok := strings.CutPrefix(s, "0x")
	if !ok {
		t.Fatalf("golden vectors: %.24q has no 0x prefix", s)
	}
	b, err := hex.DecodeString(h)
	if err != nil {
		t.Fatalf("golden vectors: %.24q: %v", s, err)
	}
	return b
}

// Hex32 decodes a 32-byte 0x-prefixed hex string.
func Hex32(t testing.TB, s string) [32]byte {
	t.Helper()
	b := Hex(t, s)
	if len(b) != 32 {
		t.Fatalf("golden vectors: %.24q is %d bytes, want 32", s, len(b))
	}
	return [32]byte(b)
}

// U64 parses a decimal uint64 string.
func U64(t testing.TB, s string) uint64 {
	t.Helper()
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		t.Fatalf("golden vectors: %q: %v", s, err)
	}
	return v
}
